insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('guia-para-leer-un-articulo-o-texto-tecnico-sin-perderse','educacion',array['ciencias']::text[],'Guía para leer un artículo o texto técnico sin perderse','Crea una guía con pasos para leer un artículo académico o un texto técnico, decidiendo qué leer primero, cómo tomar notas y cómo saber si lo entendiste, y pruébala con un texto real.','Guía','3 semanas',20,array['Lectura técnica','Textos académicos']::text[],array['crear','resolver']::text[],'publicos',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion lectura critica. sintesis. toma de notas. redaccion. articulos de acceso abierto. un editor de notas. hoja de calculo.',$a66sld${"id": "guia-para-leer-un-articulo-o-texto-tecnico-sin-perderse", "area": "educacion", "areas2": ["ciencias"], "titulo": "Guía para leer un artículo o texto técnico sin perderse", "resumen": "Crea una guía con pasos para leer un artículo académico o un texto técnico, decidiendo qué leer primero, cómo tomar notas y cómo saber si lo entendiste, y pruébala con un texto real.", "tipo": "Guía", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Lectura técnica", "Textos académicos"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Los artículos y manuales técnicos suelen ser densos, y leerlos de principio a fin como una novela es una forma de rendirse. Muchos estudiantes los leen sin saber qué buscar, y salen sin entender.", "Una estrategia de lectura con pasos claros ahorra tiempo y mejora la comprensión."], "desarrollar": ["Define una estrategia en etapas: mirar título, resumen y conclusiones; hacer preguntas antes de leer; leer por secciones con un propósito; anotar ideas clave y dudas; y resumir al final con tus palabras. Aplícala a un artículo real de acceso abierto.", "Compara tu comprensión y tiempo con otra lectura hecha sin la estrategia, ajusta los pasos y redacta una guía de una página con un ejemplo de notas."], "ampliaciones": [{"titulo": "Lectura en otro idioma", "aporta": "añade consejos para artículos en inglés."}, {"titulo": "Formato de fichas", "aporta": "diseña una ficha para resumir artículos."}, {"titulo": "Lectura de gráficos", "aporta": "agrega cómo interpretar figuras y tablas."}], "objetivos": ["Definir una estrategia de lectura.", "Aplicarla a un texto real.", "Comparar con la lectura sin guía.", "Redactar la guía."], "habilidades": ["Lectura crítica.", "Síntesis.", "Toma de notas.", "Redacción."], "herramientas": ["Artículos de acceso abierto.", "Un editor de notas.", "Hoja de cálculo."], "lineamientos": ["Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Usa artículos de acceso abierto y cita las fuentes."], "otroSector": "La misma estrategia sirve para leer manuales, informes de consultoría o normas."}$a66sld$::jsonb,73),
('cuanto-influye-dormir-bien-en-como-rindes-un-experimento-persona','educacion',array['salud']::text[],'¿Cuánto influye dormir bien en cómo rindes? Un experimento personal','Registra tus horas de sueño durante unas semanas y compáralas con tu concentración y desempeño en tareas de estudio, para ver qué relación tiene el descanso con tu rendimiento.','Investigación','3 a 4 semanas',22,array['Sueño','Rendimiento']::text[],array['investigar']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social autoobservacion. registro de datos. graficos. analisis critico. hoja de calculo. un cuaderno de registro. un editor de graficos.',$a67sld${"id": "cuanto-influye-dormir-bien-en-como-rindes-un-experimento-persona", "area": "educacion", "areas2": ["salud"], "titulo": "¿Cuánto influye dormir bien en cómo rindes? Un experimento personal", "resumen": "Registra tus horas de sueño durante unas semanas y compáralas con tu concentración y desempeño en tareas de estudio, para ver qué relación tiene el descanso con tu rendimiento.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Sueño", "Rendimiento"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Se dice que dormir bien mejora el estudio, pero en época de exámenes muchos sacrifican el sueño. Rara vez miden qué ocurre con su concentración y con cuánto rinden en esos días.", "Un registro simple muestra tu propio patrón sin necesidad de equipos."], "desarrollar": ["Durante tres a cuatro semanas anota cada día tus horas de sueño aproximadas, tu nivel de concentración al estudiar de 1 a 5 y un indicador sencillo de rendimiento, como ejercicios resueltos en 30 minutos.", "Analiza si en los días de menos sueño bajó tu rendimiento, con gráficos simples, y escribe qué cambiarías en tu rutina. Presenta los límites del experimento, como pocos días y otros factores."], "ampliaciones": [{"titulo": "Cafeína y pantallas", "aporta": "agrega registros de cafeína y uso de pantallas por la noche."}, {"titulo": "Siestas", "aporta": "compara días con y sin siesta."}, {"titulo": "Semana de exámenes", "aporta": "analiza lo que ocurre en semanas de exámenes."}], "objetivos": ["Registrar sueño y rendimiento.", "Analizar la relación.", "Reconocer los límites del registro.", "Proponer cambios."], "habilidades": ["Autoobservación.", "Registro de datos.", "Gráficos.", "Análisis crítico."], "herramientas": ["Hoja de cálculo.", "Un cuaderno de registro.", "Un editor de gráficos."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Este proyecto no da diagnósticos ni consejos médicos: si tienes problemas de sueño persistentes, consulta a un profesional de la salud.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar."], "otroSector": "El mismo registro sirve para analizar descanso y desempeño en un trabajo."}$a67sld$::jsonb,74),
('como-hacer-buenas-preguntas-en-clase-y-en-consultas-con-docentes','educacion',array['sociedad']::text[],'Cómo hacer buenas preguntas en clase y en consultas con docentes','Diseña una guía para formular preguntas claras y útiles en clase y en consultas, con ejemplos de preguntas vagas y su versión mejorada, y pruébala en tus propias consultas.','Guía','2 a 3 semanas',18,array['Preguntas','Comunicación académica']::text[],array['crear','resolver']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion comunicacion. formulacion de preguntas. redaccion. autoevaluacion. un editor de documentos. una hoja de registro. companeros para practicar.',$a68sld${"id": "como-hacer-buenas-preguntas-en-clase-y-en-consultas-con-docentes", "area": "educacion", "areas2": ["sociedad"], "titulo": "Cómo hacer buenas preguntas en clase y en consultas con docentes", "resumen": "Diseña una guía para formular preguntas claras y útiles en clase y en consultas, con ejemplos de preguntas vagas y su versión mejorada, y pruébala en tus propias consultas.", "tipo": "Guía", "tiempo": "2 a 3 semanas", "horas": 18, "etiquetas": ["Preguntas", "Comunicación académica"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Muchos estudiantes no preguntan por temor a quedar mal, o preguntan de una forma tan vaga que cuesta responder. Una buena pregunta ayuda a que el docente entienda dónde está la duda y a que el estudiante entienda mejor.", "Aprender a preguntar es una habilidad que se puede practicar."], "desarrollar": ["Reúne ejemplos de preguntas que haces o escuchas en clase, y clasifícalos como vagas, específicas o de reflexión. Reescribe las vagas para que digan qué se intentó, dónde está la duda y qué se espera saber.", "Elabora una guía con una plantilla de pregunta de tres partes y ejemplos reales. Pruébala en tres consultas con docentes o compañeros y compara cómo fueron las respuestas con las de antes."], "ampliaciones": [{"titulo": "Preguntas por correo", "aporta": "adapta la guía a consultas por escrito."}, {"titulo": "Miedo a preguntar", "aporta": "recoge ideas para animar a participar."}, {"titulo": "Preguntas en grupo", "aporta": "practica con compañeros una sesión de preguntas."}], "objetivos": ["Clasificar preguntas.", "Reescribir las vagas.", "Redactar una guía.", "Probarla en consultas reales."], "habilidades": ["Comunicación.", "Formulación de preguntas.", "Redacción.", "Autoevaluación."], "herramientas": ["Un editor de documentos.", "Una hoja de registro.", "Compañeros para practicar."], "lineamientos": ["No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "No uses nombres de docentes en tus ejemplos.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "La misma guía sirve para pedir ayuda a un colega o preguntar en reuniones de trabajo."}$a68sld$::jsonb,75),
('errores-tipicos-de-quienes-empiezan-a-programar-y-como-ayudarles','educacion',array['tecnologia']::text[],'Errores típicos de quienes empiezan a programar y cómo ayudarles','Identifica los errores más comunes de principiantes en programación, descubre por qué ocurren y diseña ejercicios y explicaciones que ayuden a evitarlos.','Análisis','3 a 4 semanas',24,array['Aprender a programar','Errores comunes']::text[],array['investigar','crear']::text[],'propios',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion programacion basica. analisis de errores. didactica. comunicacion. un editor de codigo. un lenguaje de programacion sencillo. un editor de documentos.',$a69sld${"id": "errores-tipicos-de-quienes-empiezan-a-programar-y-como-ayudarles", "area": "educacion", "areas2": ["tecnologia"], "titulo": "Errores típicos de quienes empiezan a programar y cómo ayudarles", "resumen": "Identifica los errores más comunes de principiantes en programación, descubre por qué ocurren y diseña ejercicios y explicaciones que ayuden a evitarlos.", "tipo": "Análisis", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Aprender a programar", "Errores comunes"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Quien empieza a programar suele tropezar con errores de sintaxis, de lógica o de confusión entre conceptos como variable y valor. Muchos se frustran y creen que no sirven, cuando en realidad esos errores son típicos y esperables.", "Conocerlos y explicarlos bien ahorra tiempo y frustración a quienes empiezan."], "desarrollar": ["Reúne, con permiso, ejemplos de código con errores de cinco a diez principiantes, o de tus propios primeros programas, y clasifica los errores por tipo: sintaxis, lógica, malentendidos de conceptos y malos hábitos.", "Para los cinco errores más frecuentes, escribe una explicación sencilla de por qué ocurren, cómo detectarlos y un ejercicio corto de práctica. Pruébalo con un principiante y ajusta."], "ampliaciones": [{"titulo": "Mensajes de error", "aporta": "explica cómo leer mensajes de error comunes."}, {"titulo": "Depuración", "aporta": "enseña un proceso básico para encontrar errores."}, {"titulo": "Lista de verificación", "aporta": "crea una lista para revisar un programa antes de entregarlo."}], "objetivos": ["Clasificar errores de principiantes.", "Explicar sus causas.", "Diseñar ejercicios.", "Probarlos con un principiante."], "habilidades": ["Programación básica.", "Análisis de errores.", "Didáctica.", "Comunicación."], "herramientas": ["Un editor de código.", "Un lenguaje de programación sencillo.", "Un editor de documentos."], "lineamientos": ["No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Usa código de ejemplo anónimo o propio y no publiques trabajos de otros sin permiso.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "La misma guía sirve para enseñar a usar una hoja de cálculo avanzada o una herramienta de análisis."}$a69sld$::jsonb,76),
('ingles-tecnico-para-tu-carrera-el-vocabulario-que-si-se-usa','educacion',array['tecnologia','sociedad']::text[],'Inglés técnico para tu carrera: el vocabulario que sí se usa','Extrae de textos reales de tu carrera, como manuales, artículos y documentación, el vocabulario en inglés que más aparece y arma un glosario con ejemplos y una forma de practicarlo.','Guía','3 a 4 semanas',22,array['Inglés','Vocabulario técnico']::text[],array['investigar','crear']::text[],'publicos',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion lectura tecnica en ingles. analisis de frecuencia. organizacion de informacion. autoestudio. textos de acceso abierto. hoja de calculo. un diccionario confiable.',$a70sld${"id": "ingles-tecnico-para-tu-carrera-el-vocabulario-que-si-se-usa", "area": "educacion", "areas2": ["tecnologia", "sociedad"], "titulo": "Inglés técnico para tu carrera: el vocabulario que sí se usa", "resumen": "Extrae de textos reales de tu carrera, como manuales, artículos y documentación, el vocabulario en inglés que más aparece y arma un glosario con ejemplos y una forma de practicarlo.", "tipo": "Guía", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Inglés", "Vocabulario técnico"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Muchos estudiantes estudian inglés general y se encuentran con otro lenguaje al leer artículos o documentación técnica. Saber qué palabras aparecen con más frecuencia en su campo ahorra mucho tiempo.", "Un glosario hecho con textos reales de tu carrera es más útil que una lista genérica."], "desarrollar": ["Reúne diez a quince textos en inglés de tu carrera de acceso abierto, cuenta qué términos técnicos aparecen con más frecuencia y selecciona los 50 más útiles. Para cada uno anota la traducción, un ejemplo real y la categoría.", "Arma un glosario y un plan de práctica con repaso espaciado, pruébalo durante tres semanas leyendo un artículo nuevo y mide cuántos términos reconoces ahora frente a antes."], "ampliaciones": [{"titulo": "Falsos amigos", "aporta": "agrega palabras que se parecen al español pero significan otra cosa."}, {"titulo": "Frases comunes", "aporta": "añade frases típicas de los artículos."}, {"titulo": "Pronunciación", "aporta": "agrega la pronunciación de los términos difíciles."}], "objetivos": ["Extraer vocabulario de textos reales.", "Seleccionar los términos más útiles.", "Armar un glosario.", "Medir el avance."], "habilidades": ["Lectura técnica en inglés.", "Análisis de frecuencia.", "Organización de información.", "Autoestudio."], "herramientas": ["Textos de acceso abierto.", "Hoja de cálculo.", "Un diccionario confiable."], "lineamientos": ["Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Usa textos de acceso abierto y cita las fuentes.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir."], "otroSector": "El mismo método sirve para armar glosarios de otros idiomas o de otro campo profesional."}$a70sld$::jsonb,77),
('como-evaluar-un-curso-en-linea-o-tutorial-antes-de-dedicarle-tie','educacion',array['tecnologia']::text[],'Cómo evaluar un curso en línea o tutorial antes de dedicarle tiempo','Crea una lista de verificación para decidir si un curso en línea o un tutorial vale la pena, mirando el programa, el instructor, las actividades, las opiniones y el tiempo real que exige.','Guía','2 a 3 semanas',18,array['Cursos en línea','Evaluación']::text[],array['crear','resolver']::text[],'propios',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion evaluacion de recursos. pensamiento critico. seleccion de informacion. redaccion. plataformas de cursos. hoja de calculo. un editor de documentos.',$a71sld${"id": "como-evaluar-un-curso-en-linea-o-tutorial-antes-de-dedicarle-tie", "area": "educacion", "areas2": ["tecnologia"], "titulo": "Cómo evaluar un curso en línea o tutorial antes de dedicarle tiempo", "resumen": "Crea una lista de verificación para decidir si un curso en línea o un tutorial vale la pena, mirando el programa, el instructor, las actividades, las opiniones y el tiempo real que exige.", "tipo": "Guía", "tiempo": "2 a 3 semanas", "horas": 18, "etiquetas": ["Cursos en línea", "Evaluación"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Hay muchos cursos y tutoriales gratuitos y de pago, y es fácil gastar horas en uno que no enseña lo que promete. Las calificaciones por estrellas dicen poco sobre si realmente sirve.", "Una forma ordenada de evaluar antes de empezar ahorra tiempo y dinero."], "desarrollar": ["Define de seis a ocho criterios, como objetivos claros, programa detallado, ejercicios prácticos, actualidad, experiencia del instructor y tiempo estimado. Aplícalos a tres cursos o tutoriales del mismo tema.", "Compara tu evaluación con lo que experimentaste al estudiar la primera hora de cada uno, ajusta la lista y arma una guía final con ejemplos de señales de alerta."], "ampliaciones": [{"titulo": "Versión rápida", "aporta": "crea una versión de cinco preguntas para usar en cinco minutos."}, {"titulo": "Cursos de pago", "aporta": "agrega criterios para decidir si vale el costo."}, {"titulo": "Opiniones", "aporta": "analiza cómo interpretar reseñas."}], "objetivos": ["Definir criterios de evaluación.", "Aplicarlos a cursos reales.", "Contrastar con la experiencia.", "Redactar la guía."], "habilidades": ["Evaluación de recursos.", "Pensamiento crítico.", "Selección de información.", "Redacción."], "herramientas": ["Plataformas de cursos.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Usa herramientas que ya existan y cuyas condiciones de uso respetes; no subas datos de otras personas a plataformas sin su permiso.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Describe los cursos con respeto y sin atacar a instructores."], "otroSector": "La misma lista sirve para evaluar herramientas, proveedores o capacitaciones en el trabajo."}$a71sld$::jsonb,78)
